"""================================================================================                        PROJETO IOTEC - ECOSSISTEMA ENTERPRISE                   DIAGNÓSTICO TÉCNICO E TOUR DE MONETIZAÇÃO================================================================================ Autora/Responsável : Bruna Versão             : 1.0.0 Enterprise Objetivo           : Mapear arquitetura local, validar infraestrutura em nuvem                      (Render/Netlify) e auditagem do fluxo de receita (PayPal).================================================================================"""import osimport sysimport jsonimport datetime# Arquivos essenciais do projeto para auditagem de monetizaçãoCORE_MODULES = [    "000_IOTEC_CORE.py",    "001_BOOT.py",    "013_API_GATEWAY.py",    "015_API_SERVER.py",    "015_PAYMENT_GATEWAY_ENGINE.py",    "018_EMAIL_ENGINE.py",    "019_IOTEC_PAYMENT_AUDITOR.py",    "022_IOTEC_FIRST_SALE_ORCHESTRATOR.py",    "052_WHATSAPP_BUSINESS_MANAGER.py",    "053_REVENUE_READINESS_ENGINE.py"]def print_header(title):    print("\n" + "=" * 70)    print(f"  {title.upper()}")    print("=" * 70)def audit_local_files():    print_header("1. Mapeamento de Módulos Críticos de Monetização")    found_count = 0    for module in CORE_MODULES:        exists = os.path.exists(module)        status = "[ OK ] ENCONTRADO" if exists else "[ !! ] AUSENTE"        if exists:            found_count += 1        print(f"  {module:<40} {status}")        print(f"\n  Progresso dos Módulos: {found_count}/{len(CORE_MODULES)} prontos.")def audit_environment_vars():    print_header("2. Validação de Credenciais & Infraestrutura (Env/Nuvem)")        keys_to_check = {        "PAYPAL_CLIENT_ID": "Gateway de Pagamento PayPal (CNPJ)",        "PAYPAL_SECRET": "Segredo do PayPal Live",        "DATABASE_URL": "Banco de Dados em Nuvem (PostgreSQL/Render)",        "API_SECRET_KEY": "Autenticação das APIs",        "EMAIL_HOST_USER": "Disparador de E-mail Comercial PJ"    }        for var, label in keys_to_check.items():        val = os.getenv(var)        if val:            status = f"[ OK ] Configurado ({val[:4]}***)"        else:            status = "[ X ] NÃO DETECTADO (Requer no .env)"        print(f"  {label:<45} : {status}")def generate_monetization_report():    print_header("3. Status da Esteira de Monetização Rápida")        report = {        "Data do Diagnóstico": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),        "Responsável": "Bruna",        "Frontend": "Netlify (Pronto para Build)",        "Backend / API": "Render / Gunicorn (Pronto para Deploy)",        "Checkouts": "PayPal Empresarial (Pronto para Live)",        "Ação Recomendada": "Executar '022_IOTEC_FIRST_SALE_ORCHESTRATOR.py' para ofertas diretas."    }        for key, value in report.items():        print(f"  • {key:<22} : {value}")def main():    print("""    ====================================================================               SYSTEM DIAGNOSTIC & MONETIZATION SCANNER    ====================================================================    """)    audit_local_files()    audit_environment_vars()    generate_monetization_report()        print("\n" + "=" * 70)    print("  [ PRÓXIMO PASSO ] Para iniciar a esteira de vendas, rode:")    print("  python 022_IOTEC_FIRST_SALE_ORCHESTRATOR.py")    print("=" * 70 + "\n")if __name__ == "__main__":    main()